const STORIES = [{"id":"01","era":"Origens","title":"Éden, dilúvio e Babel","refs":["GEN.2","GEN.6","GEN.8","GEN.11"],"places":["eden-1","ararat","shinar"],"note":"O mapa mostra a região de Ararate e a planície de Sinar como referências do texto. O jardim do Éden não tem localização identificada, e Ararate designa uma região e suas montanhas."},{"id":"02","era":"Patriarcas","title":"Chamado e deslocamentos de Abraão","refs":["GEN.11","GEN.12","GEN.13"],"places":["ur-1","haran","shechem","bethel-1","canaan","egypt","hebron","negeb"],"note":"Gênesis descreve Ur, Harã e Canaã, seguidas pela passagem pelo Egito e pelo retorno. A identificação de Ur dos Caldeus tem propostas alternativas."},{"id":"03","era":"Patriarcas","title":"Ló, Sodoma e Gomorra","refs":["GEN.13","GEN.19"],"places":["sodom","gomorrah","salt-sea"],"note":"Há candidatos em torno do Mar Morto. A associação de uma ruína em particular ao relato é disputada."},{"id":"04","era":"Patriarcas","title":"Isaque e os poços","refs":["GEN.26"],"places":["gerar","beersheba-1"],"note":"O relato situa as controvérsias pelos poços na região de Gerar e termina com o acordo feito em Berseba."},{"id":"05","era":"Patriarcas","title":"Jacó entre Betel, Harã e Peniel","refs":["GEN.28","GEN.29","GEN.32","GEN.35"],"places":["beersheba-1","bethel-1","haran","jabbok","penuel","shechem","bethlehem-1"],"note":"O texto liga o sonho de Jacó a Betel, sua família a Harã e sua luta noturna a Peniel, perto do Jaboque."},{"id":"06","era":"Patriarcas","title":"José e a família no Egito","refs":["GEN.37","GEN.41","GEN.45","GEN.46","GEN.47"],"places":["hebron","shechem","dothan","egypt","goshen-1","rameses"],"note":"José encontra os irmãos em Dotã. A família vai ao Egito e se estabelece na região de Gósen. O delta é um contexto geográfico amplo."},{"id":"07","era":"Êxodo e deserto","title":"Moisés no Egito e em Midiã","refs":["EXO.1","EXO.2","EXO.3"],"places":["egypt","pithom","rameses","midian","mount-sinai"],"note":"Pitom e Ramessés são citadas em Êxodo 1. Midiã orienta a fuga de Moisés. A localização de Horebe ou Sinai é debatida."},{"id":"08","era":"Êxodo e deserto","title":"Saída do Egito e travessia do mar","refs":["EXO.12","EXO.13","EXO.14","EXO.15","NUM.33"],"places":["rameses","succoth-2","etham","pi-hahiroth","migdol-1","red-sea-1"],"note":"Ramessés e Sucote são pontos de partida narrativos. A localização exata da travessia do mar de Juncos e a sequência no terreno permanecem disputadas."},{"id":"09","era":"Êxodo e deserto","title":"Aliança no Sinai e peregrinação","refs":["EXO.19","EXO.20","EXO.24","NUM.13","NUM.20","NUM.33"],"places":["mount-sinai","kadesh-barnea","edom","midian"],"note":"A aliança é situada no monte Sinai e Cades-Barneia volta a aparecer no período do deserto. Os pontos mostram candidatos e regiões de referência."},{"id":"10","era":"Êxodo e deserto","title":"Balaão, Moabe e o monte Nebo","refs":["NUM.21","NUM.22","NUM.23","NUM.24","DEU.34"],"places":["moab-1","heshbon","edom","mount-nebo","pisgah","jericho-1"],"note":"As planícies de Moabe ficam defronte de Jericó no relato. De Nebo, Moisés contempla a terra. Os candidatos de Nebo são próximos entre si."},{"id":"11","era":"Josué e juízes","title":"Jordão, Jericó e Ai","refs":["JOS.2","JOS.3","JOS.4","JOS.6","JOS.7","JOS.8"],"places":["jordan","jericho-1","ai-1"],"note":"Tel es-Sultão é o sítio da antiga Jericó. Ai tem propostas concorrentes. Identificar um sítio e datar os acontecimentos narrados são questões distintas."},{"id":"12","era":"Josué e juízes","title":"Gibeão, Hazor e a assembleia de Siquém","refs":["JOS.9","JOS.10","JOS.11","JOS.18","JOS.24"],"places":["gibeon","hazor-1","shiloh","shechem"],"note":"O recorte reúne o acordo com Gibeão, a campanha do norte, a assembleia em Siló e a renovação da aliança em Siquém."},{"id":"13","era":"Josué e juízes","title":"Débora e Baraque","refs":["JDG.4","JDG.5"],"places":["mount-tabor","kishon","megiddo","hazor-1"],"note":"O monte Tabor e o ribeiro de Quisom marcam a geografia do relato. Hazor aparece no contexto do domínio de Jabim."},{"id":"14","era":"Josué e juízes","title":"Gideão e os midianitas","refs":["JDG.6","JDG.7","JDG.8"],"places":["midian","jezreel-1","mount-gilboa","succoth-1","penuel"],"note":"O vale de Jezreel e a Transjordânia orientam a perseguição. Gilboa é uma referência de relevo próxima. Sucote aqui é a da Transjordânia."},{"id":"15","era":"Josué e juízes","title":"Sansão e os filisteus","refs":["JDG.13","JDG.14","JDG.15","JDG.16"],"places":["zorah","eshtaol","timnah-1","gaza","philistia"],"note":"Os episódios decorrem entre a Sefelá e o litoral filisteu. Gaza é o cenário da morte de Sansão."},{"id":"16","era":"Josué e juízes","title":"Rute, de Moabe a Belém","refs":["RUT.1","RUT.2","RUT.4"],"places":["moab-1","bethlehem-1"],"note":"Moabe e Belém enquadram a trajetória de Rute e Noemi. O texto não descreve a estrada exata tomada pelas duas mulheres."},{"id":"17","era":"Monarquia","title":"Samuel e a arca","refs":["1SA.1","1SA.3","1SA.4","1SA.5","1SA.6","1SA.7"],"places":["shiloh","ashdod","gath-1","ekron","beth-shemesh-1","kiriath-jearim","ramah-4"],"note":"Siló é o cenário inicial. Depois da captura, a arca é levada a cidades filisteias, retorna a Bete-Semes e segue para Quiriate-Jearim."},{"id":"18","era":"Monarquia","title":"Davi e Golias","refs":["1SA.16","1SA.17"],"places":["bethlehem-1","valley-of-elah","gath-1","philistia"],"note":"Belém é a terra de origem de Davi, Gate a de Golias e o vale de Elá o cenário do confronto descrito."},{"id":"19","era":"Monarquia","title":"Últimos dias de Saul e começo do reinado de Davi","refs":["1SA.27","1SA.28","1SA.31","2SA.2","2SA.5"],"places":["ziklag","mount-gilboa","beth-shan","hebron","jerusalem"],"note":"O combate se concentra em Gilboa. O arco da narrativa passa de Hebrom a Jerusalém, que Davi faz sede do reino."},{"id":"20","era":"Monarquia","title":"Templo de Salomão, Tiro e a rainha de Sabá","refs":["1KI.5","1KI.6","1KI.8","1KI.10"],"places":["jerusalem","tyre","sheba-1"],"note":"O texto liga a construção do templo à cooperação com Tiro e situa em Jerusalém a visita da soberana de Sabá."},{"id":"21","era":"Monarquia","title":"Reinos divididos","refs":["1KI.12","1KI.16","2KI.17"],"places":["jerusalem","shechem","bethel-1","dan","samaria-1","samaria-2"],"note":"Siquém abre a divisão política. Betel e Dã aparecem como centros cultuais de Jeroboão. Samaria se torna capital do reino do norte."},{"id":"22","era":"Monarquia","title":"Elias, Sarepta e o monte Carmelo","refs":["1KI.17","1KI.18","1KI.19"],"places":["zarephath","sidon","mount-carmel","kishon","jezreel-1","mount-sinai"],"note":"O itinerário reúne a estada em Sarepta, o confronto no Carmelo e a retirada de Elias para Horebe."},{"id":"23","era":"Monarquia","title":"Eliseu, Naamã e a mulher de Suném","refs":["2KI.4","2KI.5"],"places":["shunem","damascus","abana","pharpar","samaria-1","jordan"],"note":"Suném é o cenário do acolhimento de Eliseu. Damasco e seus rios aparecem na fala de Naamã, enquanto o Jordão é o local da lavagem."},{"id":"24","era":"Impérios e retorno","title":"Jonas, Jope e Nínive","refs":["JON.1","JON.3","JON.4"],"places":["joppa","tarshish-1","nineveh","assyria"],"note":"Jope é o porto da partida. Társis é o destino procurado, de identificação debatida. Nínive é a cidade da missão."},{"id":"25","era":"Impérios e retorno","title":"Assíria, Samaria e o cerco de Jerusalém","refs":["2KI.17","2KI.18","2KI.19","ISA.36","ISA.37"],"places":["assyria","nineveh","samaria-1","lachish","jerusalem"],"note":"O recorte reúne a conquista assíria do norte e a campanha de Senaqueribe em Judá. Laquis é mencionada como base de atuação na campanha."},{"id":"26","era":"Impérios e retorno","title":"Queda de Jerusalém e exílio na Babilônia","refs":["2KI.24","2KI.25","JER.39","JER.52","EZK.1","DAN.1"],"places":["jerusalem","babylon-1","babylonia","chebar"],"note":"Jerusalém e Babilônia enquadram as deportações. Ezequiel situa sua visão junto ao Quebar, identificado como um canal na região babilônica."},{"id":"27","era":"Impérios e retorno","title":"Ester e Neemias em Susã","refs":["EST.1","EST.2","EST.8","NEH.1","NEH.2"],"places":["susa","persia","elam","jerusalem"],"note":"Susã, no atual Irã, é a sede palaciana de Ester e o ponto inicial do relato de Neemias, que segue para Jerusalém."},{"id":"28","era":"Impérios e retorno","title":"Retorno e reconstrução de Jerusalém","refs":["EZR.1","EZR.3","EZR.6","NEH.2","NEH.6"],"places":["persia","babylon-1","jerusalem"],"note":"Os textos relacionam as autorizações persas ao retorno, ao templo e à reconstrução das muralhas."},{"id":"29","era":"Evangelhos","title":"Nascimento e infância de Jesus","refs":["MAT.2","LUK.1","LUK.2"],"places":["nazareth","bethlehem-1","jerusalem","egypt"],"note":"Mateus narra a fuga ao Egito. Lucas narra a apresentação no templo e a visita posterior a Jerusalém. Os dois incluem Belém e Nazaré."},{"id":"30","era":"Evangelhos","title":"João Batista e o batismo de Jesus","refs":["MAT.3","MRK.1","LUK.3","JHN.1"],"places":["judea-1","jordan","bethany-2"],"note":"O Jordão dá o contexto geográfico. João cita Betânia além do Jordão. A associação a um sítio exato envolve tradição e interpretação."},{"id":"31","era":"Evangelhos","title":"Caná, Nazaré e Cafarnaum","refs":["MAT.4","LUK.4","JHN.2","JHN.4"],"places":["cana","nazareth","capernaum","galilee-1","sea-of-galilee"],"note":"Caná é o cenário do casamento em João. Nazaré e Cafarnaum aparecem entre os primeiros lugares de atividade de Jesus na Galileia."},{"id":"32","era":"Evangelhos","title":"Jesus e a mulher samaritana","refs":["JHN.4"],"places":["samaria-2","sychar","shechem"],"note":"João situa o encontro em Sicar, perto do terreno associado a Jacó. A proximidade de Siquém ajuda a localizar a área."},{"id":"33","era":"Evangelhos","title":"Ministério em torno do mar da Galileia","refs":["MAT.8","MRK.4","MRK.5","MRK.6","JHN.6"],"places":["sea-of-galilee","capernaum","bethsaida-1","bethsaida-2","decapolis"],"note":"Os evangelhos relacionam travessias, curas e a multiplicação dos pães ao lago. Algumas margens e localidades têm identificações discutidas."},{"id":"34","era":"Evangelhos","title":"Do bom samaritano a Zaqueu","refs":["LUK.10","LUK.18","LUK.19"],"places":["jerusalem","jericho-2"],"note":"A estrada entre Jerusalém e Jericó serve de cenário na parábola. A cidade também aparece no relato de Zaqueu. O mapa marca as localidades."},{"id":"35","era":"Evangelhos","title":"Betânia e a entrada em Jerusalém","refs":["LUK.19","JHN.11","JHN.12"],"places":["bethany-1","mount-of-olives","jerusalem"],"note":"Betânia é a aldeia de Lázaro e suas irmãs. O monte das Oliveiras e Jerusalém situam a entrada na cidade."},{"id":"36","era":"Evangelhos","title":"Paixão e ressurreição","refs":["MAT.26","MAT.27","MAT.28","MRK.14","MRK.15","MRK.16","LUK.22","LUK.23","LUK.24","JHN.18","JHN.19","JHN.20"],"places":["jerusalem","gethsemane","mount-of-olives","golgotha","emmaus"],"note":"O recorte reúne Getsêmani, Gólgota e Emaús. Os marcadores de Gólgota e Emaús mostram identificações propostas, com diferentes graus de sustentação."},{"id":"37","era":"Atos e Apocalipse","title":"Pentecostes e dispersão","refs":["ACT.2","ACT.8"],"places":["jerusalem","samaria-1","samaria-2","gaza","caesarea"],"note":"Jerusalém é o ponto inicial. Atos 8 situa a atuação de Filipe na Samaria e na direção de Gaza, e menciona sua chegada a Cesareia."},{"id":"38","era":"Atos e Apocalipse","title":"Conversão de Saulo","refs":["ACT.9","ACT.22","ACT.26"],"places":["jerusalem","damascus","tarsus"],"note":"A experiência ocorre no caminho para Damasco. Tarso aparece como cidade de origem de Saulo e destino posterior."},{"id":"39","era":"Atos e Apocalipse","title":"Pedro em Jope e Cesareia","refs":["ACT.9","ACT.10","ACT.11"],"places":["joppa","caesarea","jerusalem"],"note":"A narrativa passa de Jope à casa de Cornélio em Cesareia. Pedro relata o ocorrido depois em Jerusalém."},{"id":"40","era":"Atos e Apocalipse","title":"Primeira viagem de Paulo e Barnabé","refs":["ACT.13","ACT.14"],"places":["antioch-1","salamis","paphos","perga","antioch-2","iconium","lystra","derbe"],"note":"O recorte acompanha a passagem por Chipre e cidades da Anatólia, com retorno à Antioquia da Síria."},{"id":"41","era":"Atos e Apocalipse","title":"Segunda viagem de Paulo, da Anatólia à Grécia","refs":["ACT.15","ACT.16","ACT.17","ACT.18"],"places":["antioch-1","derbe","lystra","troas","samothrace","philippi","thessalonica","berea","athens","corinth","cenchreae","ephesus"],"note":"Os pontos seguem as cidades de destaque em Atos, incluindo a passagem à Macedônia, o discurso em Atenas e a permanência em Corinto."},{"id":"42","era":"Atos e Apocalipse","title":"Terceira viagem de Paulo e despedida em Mileto","refs":["ACT.18","ACT.19","ACT.20","ACT.21"],"places":["antioch-1","galatia","ephesus","macedonia","troas","miletus","tyre","caesarea","jerusalem"],"note":"Atos associa este período a uma longa permanência em Éfeso. Mileto é o lugar do discurso de despedida aos presbíteros de Éfeso."},{"id":"43","era":"Atos e Apocalipse","title":"Viagem de Paulo a Roma","refs":["ACT.27","ACT.28"],"places":["caesarea","sidon","fair-havens","crete","malta","syracuse","rome"],"note":"A viagem marítima começa em Cesareia e passa por Creta. O texto situa o naufrágio em Malta e a chegada final em Roma."},{"id":"44","era":"Atos e Apocalipse","title":"Patmos e as sete igrejas","refs":["REV.1","REV.2","REV.3"],"places":["patmos","ephesus","smyrna","pergamum","thyatira","sardis","philadelphia","laodicea","asia"],"note":"Patmos é o lugar em que João situa a visão. As sete comunidades estão na província romana da Ásia, no oeste da atual Turquia."}];
